95	        Validate.notNull(dirtyDocument);
96	
97	        Document clean = Document.createShell(dirtyDocument.baseUri());
98	        int numDiscarded = copySafeNodes(dirtyDocument.body(), clean.body());
99	        return numDiscarded == 0
100	            && dirtyDocument.head().childNodes().isEmpty(); // because we only look at the body, but we start from a shell, make sure there's nothing in the head
101	    }
