133	     the tags and attributes in the input HTML are allowed by the safelist.
134	     <p>
135	     This method is intended to be used in a user interface as a validator for user input. Note that regardless of the
136	     output of this method, the input document <b>must always</b> be normalized using a method such as
137	     {@link #clean(Document)}, and the result of that method used to store or serialize the document before later reuse
138	     such as presentation to end users. This ensures that enforced attributes are set correctly, and that any
139	     differences between how a given browser and how jsoup parses the input HTML are normalized.
140	     </p>
141	     <p>Example:
142	     <pre>{@code
143	     Document inputDoc = Jsoup.parse(inputHtml);
144	     Cleaner cleaner = new Cleaner(Safelist.relaxed());
145	     boolean isValid = cleaner.isValidBodyHtml(inputHtml);
146	     Document normalizedDoc = cleaner.clean(inputDoc);
147	     }</pre>
148	     </p>
149	     @param bodyHtml HTML fragment to test
150	     @return true if no tags or attributes need to be removed; false if they do
151	     */
152	    public boolean isValidBodyHtml(String bodyHtml) {
153	        String baseUri = (safelist.preserveRelativeLinks()) ? DummyUri : ""; // fake base URI to allow relative URLs to remain valid
154	        Document clean = Document.createShell(baseUri);
155	        Document dirty = Document.createShell(baseUri);
156	        ParseErrorList errorList = ParseErrorList.tracking(1);
157	        List<Node> nodes = Parser.parseFragment(bodyHtml, dirty.body(), baseUri, errorList);
158	        dirty.body().insertChildren(0, nodes);
159	        int numDiscarded = copySafeNodes(dirty.body(), clean.body());
160	        return numDiscarded == 0 && errorList.isEmpty();
161	    }
162	
163	    /**
164	     Iterates the input and copies trusted nodes (tags, attributes, text) into the destination.
165	     */
166	    private final class CleaningVisitor implements NodeVisitor {
167	        private int numDiscarded = 0;
168	        private final Element root;
169	        private Element destination; // current element to append nodes to
170	
171	        private CleaningVisitor(Element root, Element destination) {
172	            this.root = root;
173	            this.destination = destination;
174	        }
175	
176	        @Override public void head(Node source, int depth) {
177	            if (source instanceof Element) {
178	                Element sourceEl = (Element) source;
179	
180	                if (safelist.isSafeTag(sourceEl.normalName())) { // safe, clone and copy safe attrs
181	                    ElementMeta meta = createSafeElement(sourceEl);
182	                    Element destChild = meta.el;
183	                    destination.appendChild(destChild);
184	
185	                    numDiscarded += meta.numAttribsDiscarded;
186	                    destination = destChild;
187	                } else if (source != root) { // not a safe tag, so don't add. don't count root against discarded.
188	                    numDiscarded++;
189	                }
190	            } else if (source instanceof TextNode) {
191	                TextNode sourceText = (TextNode) source;
192	                TextNode destText = new TextNode(sourceText.getWholeText());
193	                destination.appendChild(destText);
194	            } else if (source instanceof DataNode && safelist.isSafeTag(source.parent().normalName())) {
195	                DataNode sourceData = (DataNode) source;
196	                DataNode destData = new DataNode(sourceData.getWholeData());
197	                destination.appendChild(destData);
198	            } else { // else, we don't care about comments, xml proc instructions, etc
199	                numDiscarded++;
200	            }
201	        }
202	
203	        @Override public void tail(Node source, int depth) {
204	            if (source instanceof Element && safelist.isSafeTag(source.normalName())) {
205	                destination = destination.parent(); // would have descended, so pop destination stack
206	            }
207	        }
208	    }
