210	    private int copySafeNodes(Element source, Element dest) {
211	        CleaningVisitor cleaningVisitor = new CleaningVisitor(source, dest);
212	        cleaningVisitor.traverse(source);
213	        return cleaningVisitor.numDiscarded;
214	    }
