8	/**
9	 Parses and sanitizes the inline CSS of an element's {@code style} attribute, one declaration at a time. The parser is
10	 a small hand scanner rather than a full CSS parser: declarations are split on semicolons while tracking the actual
11	 nesting of strings, parentheses, block comments, and CSS backslash escapes, so that punctuation inside strings
12	 ({@code font-family: 'Calibri;'}) or functions ({@code background: url(/img;a.png)}) cannot break out of its
13	 declaration.
14	
15	 <p>Declarations with no recognizable property, an unclosed comment, an unclosed function or string (recovered only at
16	 a newline, per the CSS bad-string rule), unbalanced parentheses, or a forbidden or unverifiable external reference
17	 are dropped individually; surrounding safe declarations, other attributes, and the element's text are untouched.
18	 Each surviving declaration is scanned for references ({@code url(...)}, the legacy {@code expression(...)}
19	 function, and an {@code @import} at-rule) and every reference found is normalized through CSS unescaping and checked
20	 against the safelist's URL rules. Repeated separators and other degenerate input never throw and never cause
21	 following declarations to be joined into a rejected value.</p>
22	
23	 <p>The cleaner is stateless and thread-safe; all per-value state lives on the local parse stack.</p>
24	 */
25	final class StyleCleaner {
26	    private final Safelist safelist;
27	    private final String tagName;
28	    private final Element el;
29	
30	    private StyleCleaner(Safelist safelist, String tagName, Element el) {
31	        this.safelist = safelist;
32	        this.tagName = tagName;
33	        this.el = el;
34	    }
35	
36	    /**
37	     Cleans an inline {@code style} attribute value declaration by declaration, preserving the order and original
38	     text of every declaration that survives.
39	     @return the cleaned value, or {@code null} when no declaration survives (in which case the attribute is removed)
40	     */
41	    static String clean(Safelist safelist, String tagName, Element el, String value) {
42	        return new StyleCleaner(safelist, tagName, el).clean(value);
43	    }
44	
45	    private String clean(String value) {
46	        StringBuilder out = StringUtil.borrowBuilder();
47	        int length = value.length();
48	        int[] match = parenMatches(value); // index of each parenthesis's mate, or -1 when unmatched
49	        int[] opens = new int[length]; // positions of the currently open parentheses
50	        int segStart = 0;
51	        int parenDepth = 0;
52	        boolean segmentBad = false; // this segment already contains a malformed construct
53	        int i = 0;
54	        while (i < length) {
55	            char c = value.charAt(i);
56	            if (c == '\\') { // CSS escape: the next code unit is literal, even '\;' or '\"'
57	                i += 2;
58	                continue;
59	            }
60	            if (c == '"' || c == '\'') {
61	                int[] quote = scanQuoted(value, i + 1, c);
62	                if (quote[1] == 1) {
63	                    i = quote[0] + 1;
64	                } else {
65	                    segmentBad = true; // a bad-string token makes only this declaration malformed
66	                    i = quote[1] == 2 ? quote[0] + 1 : quote[0]; // recover at the newline, or at the next ';'
67	                }
68	                continue;
69	            }
70	            if (c == '/' && i + 1 < length && value.charAt(i + 1) == '*') {
71	                int close = value.indexOf("*/", i + 2);
72	                if (close < 0) { // an unterminated comment swallows the tail, which is never parsed as CSS
73	                    appendSafeDeclaration(value, segStart, i, segmentBad || parenDepth != 0, out);
74	                    segStart = length;
75	                    break;
76	                }
77	                i = close + 2;
78	                continue;
79	            }
80	            if (c == '(') {
81	                opens[parenDepth++] = i;
82	            } else if (c == ')') {
83	                if (parenDepth > 0) parenDepth--;
84	                else segmentBad = true; // a stray ')' makes this declaration malformed
85	            } else if (c == ';') {
86	                if (parenDepth > 0 && match[opens[parenDepth - 1]] >= 0) {
87	                    // the ';' is content of a function that closes later (e.g. an unquoted data: URL); keep scanning
88	                    i++;
89	                    continue;
90	                }
91	                // otherwise end here; a function that never closes only invalidates this declaration
92	                appendSafeDeclaration(value, segStart, i, segmentBad || parenDepth != 0, out);
93	                segStart = i + 1;
94	                segmentBad = false;
95	                parenDepth = 0;
96	            }
97	            i++;
98	        }
99	        if (segStart < length) appendSafeDeclaration(value, segStart, length, segmentBad || parenDepth != 0, out);
100	
101	        if (out.length() == 0) {
102	            StringUtil.releaseBuilderVoid(out);
103	            return null;
104	        }
105	        return StringUtil.releaseBuilder(out);
106	    }
107	
108	    /**
109	     Computes the matching parenthesis of every balanced {@code (} and {@code )} in the value, applying the same
110	     * lexical rules (escapes, quoted strings with bad-string recovery, and comments) as the declaration walk. An
111	     * unmatched parenthesis maps to {@code -1}; a single linear pass keeps style cleaning O(n) even when a value
112	     * contains many semicolons nested in functions.
113	     */
114	    private int[] parenMatches(String value) {
115	        int length = value.length();
116	        int[] match = new int[length];
117	        Arrays.fill(match, -1);
118	        int[] stack = new int[length];
119	        int depth = 0;
120	        int i = 0;
121	        while (i < length) {
122	            char c = value.charAt(i);
123	            if (c == '\\') { i += 2; continue; }
124	            if (c == '"' || c == '\'') {
125	                int[] quote = scanQuoted(value, i + 1, c);
126	                i = quote[1] == 0 ? quote[0] : quote[0] + 1; // at the recovered ';', or past the quote/newline
127	                continue;
128	            }
129	            if (c == '/' && i + 1 < length && value.charAt(i + 1) == '*') {
130	                int close = value.indexOf("*/", i + 2);
131	                if (close < 0) break;
132	                i = close + 2;
133	                continue;
134	            }
135	            if (c == '(') {
136	                stack[depth++] = i;
137	            } else if (c == ')') {
138	                if (depth > 0) {
139	                    int open = stack[--depth];
140	                    match[open] = i;
141	                    match[i] = open;
142	                }
143	            }
144	            i++;
145	        }
146	        return match;
147	    }
148	
149	    /**
150	     * <ul>
151	     *   <li>state {@code 1}: the closing quote was found at {@code end};</li>
152	     *   <li>state {@code 2}: the string was recovered at the newline at {@code end} (the CSS bad-string rule; later
153	     *       declarations stay independently parseable);</li>
154	     *   <li>state {@code 0}: neither quote nor newline remains; {@code end} is the index of the first semicolon at
155	     *       or after the opening quote (the malformed declaration is cut there), or the value length when none.</li>
156	     * </ul>
157	     */
158	    private int[] scanQuoted(String value, int from, char quote) {
159	        int length = value.length();
160	        int firstSemi = -1;
161	        for (int i = from; i < length; i++) {
162	            char c = value.charAt(i);
163	            if (c == '\\') { i++; continue; }
164	            if (c == quote) return new int[] {i, 1};
165	            if (c == '\n' || c == '\r') return new int[] {i, 2}; // bad-string recovery at a CSS newline
166	            if (c == ';' && firstSemi < 0) firstSemi = i;
167	        }
168	        return new int[] {firstSemi >= 0 ? firstSemi : length, 0};
169	    }
170	
171	    /**
172	     Validates the declaration at {@code [start, end)} and, when safe, appends its verbatim text to {@code out}.
173	     @param structurallyBad the containing walk already found a malformed construct (a bad-string token)
174	     */
175	    private void appendSafeDeclaration(String value, int start, int end, boolean structurallyBad, StringBuilder out) {
176	        if (structurallyBad) return;
177	        int p = skipSpaceAndComments(value, start, end);
178	        int q = end;
179	        while (q > p && isCssSpace(value.charAt(q - 1))) q--;
180	        if (p == q) return; // whitespace-only fragment, e.g. from a duplicated ';'
181	        int nameStart = p;
182	
183	        // an at-rule in a declaration position: only @import is meaningful inline, and its reference must pass
184	        if (value.charAt(p) == '@') {
185	            if (isSafeImportDeclaration(value, p, q)) append(out, value, start, q);
186	            return;
187	        }
188	        // property: a plain CSS identifier (including a vendor prefix such as -webkit-*) or a custom property
189	        // (--name). Escapes, comments, and quotes are not accepted in a declaration name.
190	        boolean custom = false;
191	        if (value.charAt(p) == '-') {
192	            if (p + 1 < end && value.charAt(p + 1) == '-') {
193	                p += 2;
194	                custom = true;
195	                if (p >= q || !isIdentChar(value.charAt(p))) return; // "--" alone is not a property name
196	                while (p < q && isIdentChar(value.charAt(p))) p++;
197	            } else {
198	                if (p + 1 >= q || !isIdentStart(value.charAt(p + 1))) return; // a bare '-' is not a property name
199	                p++; // let the ordinary identifier run consume the vendor-prefixed remainder
200	            }
201	        }
202	        if (!custom) {
203	            if (p >= q || !isIdentStart(value.charAt(p))) return; // no property name
204	            do { p++; } while (p < q && isIdentChar(value.charAt(p)));
205	        }
206	        p = skipSpaceAndComments(value, p, q); // whitespace/comments may sit between the name and the ':'
207	        if (p >= q || value.charAt(p) != ':') return; // no ':' (empty fragment, junk, duplicate ';')
208	        p++; // step past ':'
209	
210	        if (isDangerousProperty(value, nameStart, p - 1)) return; // known script-entry properties, regardless of value
211	        // a custom property (--name) holds arbitrary free text: its value is scanned as one string, so a colon that is
212	        // not part of a reference (e.g. "--x: https://example.com" or a time such as "12:00"), a stray quote, or an
213	        // at-keyword other than @import is preserved verbatim; only its references decide its fate
214	        boolean safe = custom
215	            ? freeTextIsSafe(value.substring(p, q))
216	            : referencesAreSafe(value, p, q);
217	        if (safe) append(out, value, start, q);
218	    }
219	
220	    /** Appends a surviving declaration, separated from any earlier ones by a single semicolon. */
221	    private void append(StringBuilder out, String value, int from, int to) {
222	        if (out.length() > 0) out.append(';');
223	        out.append(value, from, to);
224	    }
225	
226	    /**
227	     Validates an entire {@code @import} declaration: its leading reference (a quoted URL or a {@code url(...)}) must
228	     * pass the URL rules, and any trailing layer/media/supports conditions must themselves contain no unsafe
229	     * reference.
230	     */
231	    private boolean isSafeImportDeclaration(String value, int at, int end) {
232	        int i = at + 1;
233	        if (!matchesName(value, i, end, "import")) return false;
234	        i += 6;
235	        while (i < end && isCssSpace(value.charAt(i))) i++;
236	        if (i == end) return false;
237	        int afterRef;
238	        char c = value.charAt(i);
239	        if (c == '"' || c == '\'') {
240	            int[] quote = scanQuoted(value, i + 1, c);
241	            if (quote[1] != 1) return false;
242	            if (!safelist.isSafeStyleUrl(tagName, el, unescape(value.substring(i + 1, quote[0])))) return false;
243	            afterRef = quote[0] + 1;
244	        } else if (matchesName(value, i, end, "url")) {
245	            int k = skipSeparators(value, i + 3, end);
246	            if (k >= end || value.charAt(k) != '(') return false;
247	            int argEnd = matchingParen(value, k + 1, end);
248	            if (argEnd < 0 || !isSafeUrlArgument(value, k + 1, argEnd)) return false;
249	            afterRef = argEnd + 1;
250	        } else {
251	            return false;
252	        }
253	        return referencesAreSafe(value, afterRef, end);
254	    }
255	
256	    /** Advances past CSS whitespace and complete block comments; an unterminated comment runs to {@code end}. */
257	    private int skipSpaceAndComments(String value, int i, int end) {
258	        while (i < end) {
259	            char c = value.charAt(i);
260	            if (isCssSpace(c)) { i++; continue; }
261	            if (c == '/' && i + 1 < end && value.charAt(i + 1) == '*') {
262	                int close = value.indexOf("*/", i + 2);
263	                if (close < 0) return end;
264	                i = close + 2;
265	                continue;
266	            }
267	            break;
268	        }
269	        return i;
270	    }
271	
272	    /** Whitespace and comments may separate a function name from its opening parenthesis ({@code url/**\/( ... )}). */
273	    private int skipSeparators(String value, int i, int end) {
274	        return skipSpaceAndComments(value, i, end);
275	    }
276	
277	    /**
278	     Denies the legacy script-entry properties that load executable or behavior-bound content even through an
279	     * otherwise allowed-looking {@code url(...)}: {@code -moz-binding} (XBL) and IE's {@code behavior}.
280	     */
281	    private boolean isDangerousProperty(String value, int from, int colon) {
282	        int p = from;
283	        while (p < colon && isCssSpace(value.charAt(p))) p++;
284	        int q = colon;
285	        while (q > p && isCssSpace(value.charAt(q - 1))) q--;
286	        String name = value.substring(p, q);
287	        return name.equalsIgnoreCase("-moz-binding") || name.equalsIgnoreCase("behavior");
288	    }
289	
290	    /**
291	     Walks a declaration value in a single lexical pass: strings, comments, escapes, and balanced functions are
292	     recognized exactly as in declaration splitting. Block comments are skipped entirely (their text is never parsed
293	     as CSS); string contents are still scanned for a concealed {@code url(...)}-shaped reference, because when the
294	     string is itself the argument of {@code url()} the browser unescapes it before fetching; every {@code url(...)}
295	     argument, an {@code @import} reference, and the legacy {@code expression(...)} function is normalized and checked
296	     against the safelist. Unbalanced parentheses, an unterminated string or comment, or any failed reference check
297	     rejects the declaration.
298	     */
299	    private boolean referencesAreSafe(String value, int start, int end) {
300	        int parenDepth = 0;
301	        int i = start;
302	        while (i < end) {
303	            char c = value.charAt(i);
304	            if (c == '\\') { i += 2; continue; }
305	            if (c == '"' || c == '\'') {
306	                int[] quote = scanQuoted(value, i + 1, c);
307	                if (quote[1] != 1) return false; // no bad-string recovery inside a value being checked
308	                if (!freeTextIsSafe(value.substring(i + 1, quote[0]))) return false;
309	                i = quote[0] + 1;
310	                continue;
311	            }
312	            if (c == '/' && i + 1 < end && value.charAt(i + 1) == '*') {
313	                int close = value.indexOf("*/", i + 2);
314	                if (close < 0 || close >= end) return false; // unterminated comment within the declaration
315	                // comment text is never a declaration, but a reference concealed in a comment must still pass the
316	                // same URL rules so that a rejected URL can never survive in the emitted attribute
317	                if (!freeTextIsSafe(value.substring(i + 2, close))) return false;
318	                i = close + 2;
319	                continue;
320	            }
321	            if (c == '(') { parenDepth++; i++; continue; }
322	            if (c == ')') {
323	                if (parenDepth == 0) return false; // unmatched ')'
324	                parenDepth--;
325	                i++;
326	                continue;
327	            }
328	            if (c == '@') return false; // no at-rule (e.g. a buried @import) is valid inside a declaration value
329	            if (isIdentStart(c) || c == '-') {
330	                int[] name = readName(value, i, end);
331	                int nameEnd = name[0];
332	                String fnName = name[1] == 1 ? unescape(value.substring(i, nameEnd)) : value.substring(i, nameEnd);
333	                int j = skipSeparators(value, nameEnd, end);
334	                if (j < end && value.charAt(j) == '(') {
335	                    int argEnd = matchingParen(value, j + 1, end);
336	                    if (argEnd < 0) return false;
337	                    // a function name whose escapes decode to punctuation (e.g. "l\;expression") is not a real CSS
338	                    // function token; reject rather than risk it being read as two tokens by a quirky engine
339	                    if (!isPlainName(fnName)) return false;
340	                    if (fnName.equalsIgnoreCase("expression")) return false; // legacy JScript entry point
341	                    if (fnName.equalsIgnoreCase("url") && !isSafeUrlArgument(value, j + 1, argEnd)) return false;
342	                    i = j; // resume at '(' so a nested url()/expression() inside the arguments is also checked
343	                    continue;
344	                }
345	                i = nameEnd;
346	                continue;
347	            }
348	            i++;
349	        }
350	        return parenDepth == 0;
351	    }
352	
353	    /** Tests that a function name is a plain identifier, with no escape that decoded to punctuation or whitespace. */
354	    private static boolean isPlainName(String name) {
355	        int length = name.length();
356	        if (length == 0) return false;
357	        for (int k = 0; k < length; k++) {
358	            char c = name.charAt(k);
359	            boolean ok = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
360	                || (c >= '0' && c <= '9') || c == '-' || c == '_';
361	            if (!ok) return false;
362	        }
363	        return true;
364	    }
365	
366	    /**
367	     Reads a CSS name token (identifier characters, plus backslash escapes) from {@code from}. Returns
368	     {@code [end, escaped]}: {@code end} is the index after the token, and {@code escaped} is 1 when it contained a
369	     backslash. A leading run of dashes is consumed so that e.g. {@code -moz-binding} reads as one token.
370	     */
371	    private int[] readName(String value, int from, int end) {
372	        int i = from;
373	        int escaped = 0;
374	        while (i < end) {
375	            char c = value.charAt(i);
376	            if (c == '\\') {
377	                if (i + 1 >= end) break;
378	                escaped = 1;
379	                i += 2;
380	                continue;
381	            }
382	            if (isIdentChar(c)) { i++; continue; }
383	            break;
384	        }
385	        return new int[] {i, escaped};
386	    }
387	
388	    /**
389	     Applies the same URL rules to text that is not itself parsed as declarations — the body of a quoted string, a
390	     * block comment, or the value of a custom property. Such text cannot introduce a declaration, but a rejected
391	     * reference must not survive in the emitted style, so every {@code url(...)}-shaped reference and every
392	     * {@code @import} reference is extracted (CSS-escapes normalized) and checked; the legacy
393	     * {@code expression(...)} function is always rejected.
394	     */
395	    private boolean freeTextIsSafe(String text) {
396	        int end = text.length();
397	        int i = 0;
398	        while (i < end) {
399	            char c = text.charAt(i);
400	            if (c == '\\') { i += 2; continue; }
401	            if (c == '@' && matchesName(text, i + 1, end, "import")) {
402	                if (!freeTextImportIsSafe(text, i + 7, end)) return false;
403	                i += 7;
404	                continue;
405	            }
406	            if (isIdentStart(c) || c == '-') {
407	                int[] name = readName(text, i, end);
408	                int j = skipSeparators(text, name[0], end);
409	                if (j < end && text.charAt(j) == '(') {
410	                    String fnName = name[1] == 1 ? unescape(text.substring(i, name[0])) : text.substring(i, name[0]);
411	                    int argEnd = matchingParen(text, j + 1, end);
412	                    if (argEnd < 0) return false;
413	                    if (!isPlainName(fnName)) return false;
414	                    if (fnName.equalsIgnoreCase("expression")) return false;
415	                    if (fnName.equalsIgnoreCase("url") && !isSafeUrlArgument(text, j + 1, argEnd)) return false;
416	                    i = j; // resume at '(' so a nested url()/expression() in the arguments is also checked
417	                    continue;
418	                }
419	                i = name[0];
420	                continue;
421	            }
422	            i++;
423	        }
424	        return true;
425	    }
426	
427	    /** Checks the quoted-string or {@code url(...)} reference of an {@code @import} found in free text. */
428	    private boolean freeTextImportIsSafe(String text, int from, int end) {
429	        int i = from;
430	        while (i < end && isCssSpace(text.charAt(i))) i++;
431	        if (i >= end) return true; // a dangling "@import" with no reference is inert junk
432	        char c = text.charAt(i);
433	        if (c == '"' || c == '\'') {
434	            int[] quote = scanQuoted(text, i + 1, c);
435	            if (quote[1] != 1) return false;
436	            return safelist.isSafeStyleUrl(tagName, el, unescape(text.substring(i + 1, quote[0])));
437	        }
438	        if (matchesName(text, i, end, "url")) {
439	            int k = skipSeparators(text, i + 3, end);
440	            if (k >= end || text.charAt(k) != '(') return false;
441	            int argEnd = matchingParen(text, k + 1, end);
442	            return argEnd >= 0 && isSafeUrlArgument(text, k + 1, argEnd);
443	        }
444	        return false;
445	    }
446	
447	    /** Extracts and validates the single URL argument of a {@code url(...)} function. */
448	    private boolean isSafeUrlArgument(String value, int from, int end) {
449	        int i = from;
450	        while (i < end && isCssSpace(value.charAt(i))) i++;
451	        int j = end;
452	        while (j > i && isCssSpace(value.charAt(j - 1))) j--;
453	        if (i == j) return false; // url() with no reference
454	
455	        char first = value.charAt(i);
456	        String raw;
457	        if (first == '"' || first == '\'') {
458	            int[] quote = scanQuoted(value, i + 1, first);
459	            if (quote[1] != 1 || quote[0] + 1 != j) return false; // unterminated or trailing junk inside the quotes
460	            raw = value.substring(i + 1, quote[0]);
461	            for (int k = 0; k < raw.length(); k++) { // the closing quote may not appear inside, escaped or not
462	                char c = raw.charAt(k);
463	                if (c == '\\') { k++; continue; }
464	                if (c == first) return false;
465	            }
466	        } else {
467	            // an unquoted URL token is a single run: bare whitespace or quotes are syntax errors, not part of the URL
468	            for (int k = i; k < j; k++) {
469	                char c = value.charAt(k);
470	                if (c == '\\') { k++; continue; }
471	                if (c == '"' || c == '\'' || isCssSpace(c)) return false;
472	            }
473	            raw = value.substring(i, j);
474	        }
475	        return safelist.isSafeStyleUrl(tagName, el, unescape(raw));
476	    }
477	
478	    /** Returns the index of the ')' matching the '(' whose argument starts at {@code from}, or {@code -1}. */
479	    private int matchingParen(String value, int from, int end) {
480	        int depth = 1;
481	        int i = from;
482	        while (i < end) {
483	            char c = value.charAt(i);
484	            if (c == '\\') { i += 2; continue; }
485	            if (c == '"' || c == '\'') {
486	                int[] quote = scanQuoted(value, i + 1, c);
487	                if (quote[1] != 1) return -1;
488	                i = quote[0] + 1;
489	                continue;
490	            }
491	            if (c == '(') depth++;
492	            else if (c == ')') { depth--; if (depth == 0) return i; }
493	            i++;
494	        }
495	        return -1;
496	    }
497	
498	    private boolean matchesName(String value, int from, int end, String name) {
499	        int len = name.length();
500	        if (from + len > end) return false;
501	        for (int k = 0; k < len; k++) {
502	            char a = value.charAt(from + k);
503	            char b = name.charAt(k);
504	            if (a != b && a != Character.toUpperCase(b)) return false;
505	        }
506	        return true;
507	    }
508	
509	    /**
510	     Decodes CSS backslash escapes in a URL token, mirroring how a browser reads the reference: a {@code \}{@code hEX}
511	     run (up to six hex digits, optionally followed by one whitespace delimiter) becomes its code point, and any other
512	     backslash-prefixed character collapses to that character. An obfuscated scheme such as {@code java\73cript:} or
513	     {@code \6a avascript:} therefore cannot hide from the protocol check. A NUL code point is dropped, matching the
514	     CSS requirement to replace it.
515	     */
516	    static String unescape(String value) {
517	        if (value.indexOf('\\') == -1) return value;
518	        int length = value.length();
519	        StringBuilder sb = null;
520	        int i = 0;
521	        while (i < length) {
