530	                while (hexEnd < length && hexEnd - h < 6 && isHex(value.charAt(hexEnd))) hexEnd++;
531	                if (hexEnd > h) {
532	                    int code = Integer.parseInt(value.substring(h, hexEnd), 16);
533	                    if (hexEnd < length && isCssSpace(value.charAt(hexEnd))) hexEnd++;
