323	        // six hex digits above the Unicode range become U+FFFD; the declaration is still validated, never thrown on
324	        assertEquals("<div style=\"color:red\">x</div>",
325	            clean("<div style=\"background:url(http\\af0aab x);color:red\">x</div>"));
