329	        Safelist safelist = Safelist.basicWithImages();
330	        assertEquals("<img src=\"https://example.com/x.png\">",
331	            org.jsoup.TextUtil.stripNewlines(clean("<img src='/x.png'>", Base, safelist)));
332	        assertEquals("<img>",
333	            org.jsoup.TextUtil.stripNewlines(clean("<img src='javascript:alert(1)'>", Base, safelist)));
334	    }
