package org.jsoup.safety;

import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class StyleProbeTest {
    private static final String Base = "https://example.com/a/b";
    private static Safelist sl() { return Safelist.relaxed().addAttributes(":all", "style"); }
    private static String clean(String styleValue) {
        String html = "<div style=\"" + styleValue + "\">x</div>";
        return new Cleaner(sl()).clean(Jsoup.parseBodyFragment(html, Base)).body().html();
    }

    @Test void escapedFunctionBypassesAreRejected() {
        String[] attacks = {
            "background:\\75 rl(javascript:alert(1))",
            "background:\\000075 rl(javascript:alert(1))",
            "background:\\75rl(javascript:alert(1))",
            "background:expres\\73 ion(alert(1))",
            "background:\\65 xpression(alert(1))",
            "--x: \\75 rl(javascript:alert(1)); color:red",
            "color:red; background:\\75 rl(javascript:1)",
            "background:\\75\\72\\6c(javascript:1)",
            "background:var(--x, \\75 rl(javascript:1))",
            "background:\\65\\78\\70\\72\\65\\73\\73 ion(1)",
        };
        for (String a : attacks) {
            String out = clean(a);
            assertFalse(out.contains("javascript"), a);
            assertFalse(out.contains("alert"), a);
            assertFalse(out.matches(".*\\\\(75|65|72|6c|78|70|73).*"), a);
        }
        // the safe sibling declaration survives on its own
        assertEquals("<div style=\"color:red\">x</div>",
            clean("color:red; background:\\75 rl(javascript:1)"));
        assertEquals("<div style=\" color:red\">x</div>",
            clean("--x: \\75 rl(javascript:alert(1)); color:red"));
    }

    @Test void legitimateEscapesAreNotFalsePositives() {
        // escaped space inside an unquoted font family identifier
        assertEquals("<div style=\"font-family: Ahem\\ Free\">x</div>",
            clean("font-family: Ahem\\ Free"));
        // an escaped letter in an ordinary identifier value
        assertEquals("<div style=\"color: re\\64\">x</div>",
            clean("color: re\\64"));
        // escaped generic function name that is not url/expression
        assertEquals("<div style=\"width:\\63 alc(100%)\">x</div>",
            clean("width:\\63 alc(100%)"));
        // safe url reached after an escaped semicolon-shaped fragment
        assertEquals("<div style=\"background:url(https://example.com/x.png)\">x</div>",
            clean("background:url(https://example.com/x.png)"));
        // custom property with escaped but safe content
        assertEquals("<div style=\"--x: a\\ b\">x</div>", clean("--x: a\\ b", ));
    }
}

