package org.jsoup.safety;

import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.junit.jupiter.api.Test;

class StyleProbeTest {
    private static final String Base = "https://example.com/a/b";
    private static Safelist sl() { return Safelist.relaxed().addAttributes(":all", "style"); }

    private static String clean(String styleValue) {
        String html = "<div style=\"" + styleValue + "\">x</div>";
        Document dirty = Jsoup.parseBodyFragment(html, Base);
        return new Cleaner(sl()).clean(dirty).body().html();
    }

    @Test void probe() {
        String[] attacks = {
            "background:\\75 rl(javascript:alert(1))",          // u escaped
            "background:\\000075 rl(javascript:alert(1))",      // 6-hex u
            "background:\\75rl(javascript:alert(1))",           // u escaped, no ws delimiter
            "background:expres\\73 ion(alert(1))",              // mid-name hex escape -> expression
            "background:\\65 xpression(alert(1))",              // e escaped -> expression
            "--x: \\75 rl(javascript:alert(1)); color:red",     // custom property
            "color:red; background:\\75 rl(javascript:1)",      // unclosed? no - balanced
            "background:URL\\28 x)(javascript:1)",              // escaped paren in name
            "background:\\u\\72\\6c(javascript:1)",             // mixed escapes in name
        };
        for (String a : attacks) {
            String out = clean(a);
            boolean bad = out.contains("javascript") || out.contains("alert") || out.contains("expression")
                || out.contains("\\75") || out.contains("\\65") || out.contains("\\73");
            System.out.println((bad ? "VULN  " : "ok    ") + a + "  =>  " + out);
        }
    }
}

