package org.jsoup.safety;

import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class StyleFuzzTest {
    private static Safelist sl() { return Safelist.relaxed().addAttributes(":all", "style"); }

    @Test void fuzzEscapedReferencesNeverLeak() {
        Random r = new Random(99);
        String[] escapes = {"\\75 ", "\\75", "\\000075 ", "\\75\\72\\6c", "\\000075\\000072\\00006c",
            "\\65\\78\\70\\72\\65\\73\\73 ", "\\65 xpression", "expres\\73 ion", "\\75r\\6c", "\\55\\52\\4c "};
        String[] payloads = {"javascript:alert(1)", "JaVaScRiPt:1", "vbscript:1", "data:text/html,x",
            "  javascript:1", "https://safe.example/x.png", "#frag"};
        String[] wrappers = {"%s(%s)", " %s(%s) ", "color:red;%s(%s);color:blue",
            "var(--x, %s(%s))", "%s ( %s )", "x;%s(%s)"};
        Safelist safelist = sl();
        for (String e : escapes) for (String p : payloads) for (String w : wrappers) {
            String v = String.format(w, e, p);
            // randomly interleave noise
            if (r.nextBoolean()) v = v + ";;'\"/*";
            String html = "<div style=\"" + v.replace("\"", "&quot;") + "\">x</div>";
            Document clean = new Cleaner(safelist).clean(Jsoup.parseBodyFragment(html, "https://example.com/base"));
            for (Element el : clean.getAllElements()) {
                String s = el.attr("style");
                if (p.toLowerCase().contains("javascript") || p.toLowerCase().contains("vbscript")
                    || p.contains("text/html")) {
                    assertFalse(s.contains("alert") || s.toLowerCase().contains("javascript")
                        || s.toLowerCase().contains("vbscript") || s.contains("text/html"), "leak: " + v);
                }
            }
        }
    }
}

